A homomorphism of \mathfrak {Setoid}-algebras (from (\mathsf {X}_0, \mathsf {eq}_0, \mathsf {eq}\eta _0, \ldots ) to (\mathsf {X}_1, \mathsf {eq}_1, \mathsf {eq}\eta _1, \ldots ))
consists of

\mathsf {X}{}^{\mathsf  M} \colon  \mathsf {X}_0 \to  \mathsf {X}_1

\mathsf {eq}{}^{\mathsf  M} \colon  \{x \;y \colon  \mathsf {X}_0\}  \to  \mathsf {eq}_0\;x\;y \to  \mathsf {eq}_1\;\lparen {}\mathsf {X}{}^{\mathsf  M}\;x\rparen {}\;\lparen {}\mathsf {X}{}^{\mathsf  M}\;y\rparen {}

\mathsf {rfl}{}^{\mathsf  M} \colon  \{x \colon  \mathsf {X}_0\}  \to  \mathsf {eq}{}^{\mathsf  M}\;\lparen {}\mathsf {rfl}_0\;x\rparen {}\;=\;\mathsf {rfl}_1\;\lparen {}\mathsf {X}{}^{\mathsf  M}\;x\rparen {}

\mathsf {sym}{}^{\mathsf  M} \colon  \{x \;y \colon  \mathsf {X}_0\} \{p \colon  \mathsf {eq}_0\;x\;y\}  \to  \mathsf {eq}{}^{\mathsf  M}\;\lparen {}\mathsf {sym}_0\;x\;y\;p\rparen {}\;=\;\mathsf {sym}_1\;\lparen {}\mathsf {X}{}^{\mathsf  M}\;x\rparen {}\;\lparen {}\mathsf {X}{}^{\mathsf  M}\;y\rparen {}\;\lparen {}\mathsf {eq}{}^{\mathsf  M}\;p\rparen {}

\mathsf {trns}{}^{\mathsf  M} \colon  \{x \;y \;z \colon  \mathsf {X}_0\} \{p \colon  \mathsf {eq}_0\;x\;y\} \{q \colon  \mathsf {eq}_0\;y\;z\}  \to  \mathsf {eq}{}^{\mathsf  M}\;\lparen {}\mathsf {trns}_0\;x\;y\;z\;p\;q\rparen {}\;=\;\mathsf {trns}_1\;\lparen {}\mathsf {X}{}^{\mathsf  M}\;x\rparen {}\;\lparen {}\mathsf {X}{}^{\mathsf  M}\;y\rparen {}\;\lparen {}\mathsf {X}{}^{\mathsf  M}\;z\rparen {}\;\lparen {}\mathsf {eq}{}^{\mathsf  M}\;p\rparen {}\;\lparen {}\mathsf {eq}{}^{\mathsf  M}\;q\rparen {}

A displayed \mathfrak {Setoid}-algebra 
(over a \mathfrak {Setoid}-algebra (\mathsf {X}, \mathsf {eq}, \mathsf {eq}\eta , \ldots ))
consists of

\mathsf {X}{}^{\mathsf  D} \colon  \mathsf {X} \to  \mathsf {Set}

\mathsf {eq}{}^{\mathsf  D} \colon  \{x \colon  \mathsf {X}\} \lparen {}x{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;x\rparen {} \{y \colon  \mathsf {X}\} \lparen {}y{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;y\rparen {}  \to  \mathsf {eq}\;x\;y \to  \mathsf {Set}

\mathsf {eq}\eta {}^{\mathsf  D} \colon  \{x \colon  \mathsf {X}\} \lparen {}x{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;x\rparen {} \{x' \colon  \mathsf {X}\} \lparen {}x'{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;x'\rparen {} \{p \colon  \mathsf {eq}\;x\;x'\} \lparen {}p{}^{\mathsf  D} \colon  \mathsf {eq}{}^{\mathsf  D}\;x{}^{\mathsf  D}\;x'{}^{\mathsf  D}\;p\rparen {} \{q \colon  \mathsf {eq}\;x\;x'\} \lparen {}q{}^{\mathsf  D} \colon  \mathsf {eq}{}^{\mathsf  D}\;x{}^{\mathsf  D}\;x'{}^{\mathsf  D}\;q\rparen {}  \to  p{}^{\mathsf  D}\;=\;q{}^{\mathsf  D}

\mathsf {rfl}{}^{\mathsf  D} \colon  \{x \colon  \mathsf {X}\} \lparen {}x{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;x\rparen {}  \to  \mathsf {eq}{}^{\mathsf  D}\;x{}^{\mathsf  D}\;x{}^{\mathsf  D}\;\lparen {}\mathsf {rfl}\;x\rparen {}

\mathsf {sym}{}^{\mathsf  D} \colon  \{x \colon  \mathsf {X}\} \lparen {}x{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;x\rparen {} \{y \colon  \mathsf {X}\} \lparen {}y{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;y\rparen {} \{p \colon  \mathsf {eq}\;x\;y\} \lparen {}p{}^{\mathsf  D} \colon  \mathsf {eq}{}^{\mathsf  D}\;x{}^{\mathsf  D}\;y{}^{\mathsf  D}\;p\rparen {}  \to  \mathsf {eq}{}^{\mathsf  D}\;y{}^{\mathsf  D}\;x{}^{\mathsf  D}\;\lparen {}\mathsf {sym}\;x\;y\;p\rparen {}

\mathsf {trns}{}^{\mathsf  D} \colon  \{x \colon  \mathsf {X}\} \lparen {}x{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;x\rparen {} \{y \colon  \mathsf {X}\} \lparen {}y{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;y\rparen {} \{z \colon  \mathsf {X}\} \lparen {}z{}^{\mathsf  D} \colon  \mathsf {X}{}^{\mathsf  D}\;z\rparen {} \{p \colon  \mathsf {eq}\;x\;y\} \lparen {}p{}^{\mathsf  D} \colon  \mathsf {eq}{}^{\mathsf  D}\;x{}^{\mathsf  D}\;y{}^{\mathsf  D}\;p\rparen {} \{q \colon  \mathsf {eq}\;y\;z\} \lparen {}q{}^{\mathsf  D} \colon  \mathsf {eq}{}^{\mathsf  D}\;y{}^{\mathsf  D}\;z{}^{\mathsf  D}\;q\rparen {}  \to  \mathsf {eq}{}^{\mathsf  D}\;x{}^{\mathsf  D}\;z{}^{\mathsf  D}\;\lparen {}\mathsf {trns}\;x\;y\;z\;p\;q\rparen {}

A section of a displayed \mathfrak {Setoid}-algebra (\mathsf {X}{}^{\mathsf  D}, \mathsf {eq}{}^{\mathsf  D}, \mathsf {eq}\eta {}^{\mathsf  D}, \ldots ) (over a \mathfrak {Setoid}-algebra (\mathsf {X}, \mathsf {eq}, \mathsf {eq}\eta , \ldots ))
consists of

\mathsf {X}{}^{\mathsf  S} \colon  \lparen {}x \colon  \mathsf {X}\rparen {}  \to  \mathsf {X}{}^{\mathsf  D}\;x

\mathsf {eq}{}^{\mathsf  S} \colon  \{x \;y \colon  \mathsf {X}\} \lparen {}p \colon  \mathsf {eq}\;x\;y\rparen {}  \to  \mathsf {eq}{}^{\mathsf  D}\;\lparen {}\mathsf {X}{}^{\mathsf  S}\;x\rparen {}\;\lparen {}\mathsf {X}{}^{\mathsf  S}\;y\rparen {}\;p

\mathsf {rfl}{}^{\mathsf  S} \colon  \{x \colon  \mathsf {X}\}  \to  \mathsf {eq}{}^{\mathsf  S}\;\lparen {}\mathsf {rfl}\;x\rparen {}\;=\;\mathsf {rfl}{}^{\mathsf  D}\;\lparen {}\mathsf {X}{}^{\mathsf  S}\;x\rparen {}

\mathsf {sym}{}^{\mathsf  S} \colon  \{x \;y \colon  \mathsf {X}\} \{p \colon  \mathsf {eq}\;x\;y\}  \to  \mathsf {eq}{}^{\mathsf  S}\;\lparen {}\mathsf {sym}\;x\;y\;p\rparen {}\;=\;\mathsf {sym}{}^{\mathsf  D}\;\lparen {}\mathsf {X}{}^{\mathsf  S}\;x\rparen {}\;\lparen {}\mathsf {X}{}^{\mathsf  S}\;y\rparen {}\;\lparen {}\mathsf {eq}{}^{\mathsf  S}\;p\rparen {}

\mathsf {trns}{}^{\mathsf  S} \colon  \{x \;y \;z \colon  \mathsf {X}\} \{p \colon  \mathsf {eq}\;x\;y\} \{q \colon  \mathsf {eq}\;y\;z\}  \to  \mathsf {eq}{}^{\mathsf  S}\;\lparen {}\mathsf {trns}\;x\;y\;z\;p\;q\rparen {}\;=\;\mathsf {trns}{}^{\mathsf  D}\;\lparen {}\mathsf {X}{}^{\mathsf  S}\;x\rparen {}\;\lparen {}\mathsf {X}{}^{\mathsf  S}\;y\rparen {}\;\lparen {}\mathsf {X}{}^{\mathsf  S}\;z\rparen {}\;\lparen {}\mathsf {eq}{}^{\mathsf  S}\;p\rparen {}\;\lparen {}\mathsf {eq}{}^{\mathsf  S}\;q\rparen {}
